
import argparse
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

parser = argparse.ArgumentParser()
parser.add_argument("--csv", default="all_actions_zweighted.csv")
parser.add_argument("--start", type=int, default=180)
parser.add_argument("--end", type=int, default=310)
parser.add_argument("--output", default="place_action_analysis.png")
args = parser.parse_args()

df = pd.read_csv(args.csv)

print("[CSV COLUMNS]", df.columns.tolist())

# Adapt to the column names generated by analyze_all_actions_12d.py.
def find_column(candidates):
    for name in candidates:
        if name in df.columns:
            return name
    raise KeyError(
        f"None of {candidates} found. "
        f"Available columns: {df.columns.tolist()}"
    )

frame_col = find_column(["frame", "frame_idx", "index"])

columns = {}
for axis in "xyz":
    columns[axis] = (
        find_column([
            f"expert_d{axis}",
            f"expert_{axis}",
            f"expert_delta_{axis}",
            f"gt_d{axis}",
        ]),
        find_column([
            f"bc_d{axis}",
            f"pred_d{axis}",
            f"bc_{axis}",
            f"pred_{axis}",
            f"pred_delta_{axis}",
        ]),
    )

# end is exclusive: 180..309
df = df[
    (df[frame_col] >= args.start)
    & (df[frame_col] < args.end)
].copy()

if df.empty:
    raise ValueError("No frames in the selected interval.")

frames = df[frame_col].to_numpy()

fig, axes = plt.subplots(
    3, 2, figsize=(15, 11), sharex="col"
)

for row, axis in enumerate("xyz"):
    expert_col, bc_col = columns[axis]

    expert = df[expert_col].to_numpy(dtype=float) * 100
    bc = df[bc_col].to_numpy(dtype=float) * 100

    expert_cum = np.cumsum(expert)
    bc_cum = np.cumsum(bc)

    # Left: individual actions (cm per policy step)
    ax = axes[row, 0]
    ax.plot(frames, expert, label="Expert", linewidth=2)
    ax.plot(frames, bc, label="BC", linewidth=1.5, alpha=0.8)
    ax.axhline(0, color="gray", linewidth=0.7)
    ax.axvline(250, color="gray", linestyle="--", alpha=0.6)
    ax.set_ylabel(f"{axis.upper()} action (cm)")
    ax.grid(alpha=0.2)

    # Right: cumulative actions (cm)
    ax = axes[row, 1]
    ax.plot(frames, expert_cum, label="Expert", linewidth=2)
    ax.plot(frames, bc_cum, label="BC", linewidth=1.5)
    ax.axvline(250, color="gray", linestyle="--", alpha=0.6)
    ax.set_ylabel(f"Cumulative {axis.upper()} (cm)")
    ax.grid(alpha=0.2)

    print(
        f"[{axis.upper()}] "
        f"Expert={expert_cum[-1]:+.3f} cm, "
        f"BC={bc_cum[-1]:+.3f} cm, "
        f"MAE={np.mean(np.abs(expert - bc)):.4f} cm"
    )

axes[0, 0].set_title("Per-frame position actions")
axes[0, 1].set_title("Cumulative position actions")

axes[0, 0].legend()
axes[0, 1].legend()

axes[-1, 0].set_xlabel("Expert demonstration frame")
axes[-1, 1].set_xlabel("Expert demonstration frame")

fig.suptitle(
    f"Visual BC Place Analysis | Frames {args.start}-{args.end - 1}",
    fontsize=15,
)
plt.tight_layout()

output = Path(args.output)
output.parent.mkdir(parents=True, exist_ok=True)
plt.savefig(output, dpi=180, bbox_inches="tight")
print(f"[SAVED] {output}")
plt.show()
